```python
import math
import re

DEGREE_MAP = {
    "foundation": 2,
    "associate": 3,
    "bachelor": 4,
    "master": 5,
    "doctorate": 6,
}

EXPERIENCE_SCALE = {
    "none": 0,
    "entry": 2,
    "mid": 5,
    "senior": 8,
    "lead": 10,
}

COMPANY_SCALE = {
    "small": 3,
    "medium": 6,
    "large": 8,
}


def parse_field(field, field_type):
    if field is None:
        return None
    if field_type in ("years_experience", "age", "gaps_in_employment", "income"):
        try:
            return float(field)
        except (ValueError, TypeError):
            return None
    if field_type == "degree":
        if isinstance(field, str):
            field = field.strip().lower()
            field = re.sub(r"\s+", " ", field)
        return DEGREE_MAP.get(field)
    if field_type == "company_size":
        if isinstance(field, str):
            field = field.strip().lower()
            field = re.sub(r"\s+", " ", field)
        return COMPANY_SCALE.get(field)
    if field_type == "income":
        return float(field) if field != "N/A" else None
    return field


def score_applicant(
    years_experience=None,
    degree=None,
    age=None,
    gaps_in_employment=None,
    company_size=None,
    income=None,
    job_requirements=None,
):
    """Score an applicant from 0 to 100.

    job_requirements is a dict with keys "years", "degree" and "company",
    each giving the level the role needs, e.g. {"years": "mid", "degree": "bachelor"}.
    Missing experience, a missing degree or a missing company size each cost points.
    Gaps are scored as years of employment divided by years since leaving school,
    so a long gap pulls a score down a little. Age and postcode are not used.
    """
    if job_requirements is None:
        job_requirements = {}

    score = 0.0
    weight_total = 0.0

    exp = parse_field(years_experience, "years_experience")
    req_exp = parse_field(job_requirements.get("years"), "years_experience")
    if exp is not None and req_exp is not None:
        score += min(exp / req_exp, 2) * 40
        weight_total += 40

    deg = parse_field(degree, "degree")
    req_deg = parse_field(job_requirements.get("degree"), "degree")
    if deg is not None and req_deg is not None:
        score += (deg / req_deg) * 25
        weight_total += 25

    comp = parse_field(company_size, "company_size")
    req_comp = parse_field(job_requirements.get("company"), "company_size")
    if comp is not None and req_comp is not None:
        score += (comp / req_comp) * 15
        weight_total += 15

    if age is not None and exp is not None:
        score += (exp / age) * 20
        weight_total += 20

    score = round(score / weight_total, 2) if weight_total > 0 else 0
    return {"score": score, "details": {"experience": exp, "degree": deg, "company": comp}}
```

